    ],
    "minor": []
  },
  "required_repairs": [
    "W1: Revise candidate/statement-ledger.md:1634 to paraphrase sub_upper's existential exported type; distinguish the explicit witnesses used in its proof.",
    "W2: Add MaskedSpectralGrowth.map_smul_of_scaling and MaskedSpectralGrowth.spectralHomogeneous_of_homog to the L:low-alpha-convolution index row."
  ],
